"""Code Dojo exercises: real Python, checked by real tests in the sandbox."""
from __future__ import annotations


def T(name, expr, expected=None, tol=1e-6, setup=None):
    t = {"name": name, "expr": expr, "tol": tol}
    if expected is not None:
        t["expected"] = expected
    if setup:
        t["setup"] = setup
    return t


