BY_ID = {e["id"]: e for e in EXERCISES}


def public(ex: dict, reveal_solution: bool = False) -> dict:
    d = {k: v for k, v in ex.items() if k not in ("solution", "tests", "setup")}
    d["tests"] = [{"name": t["name"]} for t in ex["tests"]]
    if reveal_solution:
        d["solution"] = ex["solution"]
    return d
